mapper.select:
SELECT
    I.ID, I.INQUIRY_NO, I.GUEST_ID, I.TITLE, I.CONTENT,
    I.STATUS, I.ANSWER, I.ANSWERED_BY, I.ANSWERED_AT, I.CREATED_AT
FROM INQUIRY I
WHERE I.ID = #{id}
  AND I.GUEST_ID = #{guestId}

mapper.insert:
INSERT INTO INQUIRY (ID, INQUIRY_NO, GUEST_ID, TITLE, CONTENT)
VALUES (
    INQUIRY_SEQ.NEXTVAL,
    'INQ-' || TO_CHAR(SYSDATE, 'YYYYMMDD') || '-' || LPAD(INQUIRY_SEQ.CURRVAL, 3, '0'),
    #{guestId}, #{title}, #{content}
)
